application/json.schema:
{
  "title": "Spotify Play Count & Monthly Listeners Scraper",
  "description": "Paste Spotify links. Get every track's play count, and for artists their monthly listeners and followers.",
  "type": "object",
  "schemaVersion": 1,
  "properties": {
    "urls": {
      "title": "Spotify links",
      "type": "array",
      "description": "One per line: track, album, artist or playlist links (open.spotify.com/…) or URIs (spotify:album:…).",
      "editor": "stringList",
      "prefill": [
        "https://open.spotify.com/album/4aawyAB9vmqN3uQ7FjRGTy"
      ]
    },
    "addDailyStreams": {
      "title": "Add daily streams (last 1, 7 and 30 days)",
      "type": "boolean",
      "description": "Adds streams per day for tracks we have been tracking. Tracks seen for the first time get empty values today and history from tomorrow.",
      "default": false,
      "sectionCaption": "Advanced"
    },
    "includeArtistAlbums": {
      "title": "For artist links, also scrape their albums and singles",
      "type": "boolean",
      "description": "Off: an artist link returns the artist row plus its top tracks. On: also every track of the albums and singles shown on the artist page (slower).",
      "default": false
    },
    "maxTracksPerTarget": {
      "title": "Max tracks per link",
      "type": "integer",
      "description": "0 means no limit. Large playlists and full catalogs can run to thousands of tracks.",
      "default": 0,
      "minimum": 0,
      "prefill": 50
    }
  },
  "required": [
    "urls"
  ]
}

